class Solution:
    def majorityElement(self, nums: List[int]) -> List[int]:
        ans1, ans2, vote1, vote2, n = -1, -1, 0, 0, len(nums)
        for item in nums:
            if item == ans1:
                vote1 += 1
            elif item == ans2:
