        i, j = low, mid + 1
        ######################################
        # SLIGHT MODIFICATION FROM PROBLEM 'Count Inversions'
        while i <= mid and j <= high:
            if arr[i] > 2 * arr[j]:
                ans += (mid + 1 - i)
                j += 1
            else:
                i += 1
        ######################################
        i, j = low, mid + 1
        while i <= mid and j <= high:
