class Solution:
    def copyRandomList(self, head: 'Optional[Node]') -> 'Optional[Node]':
        if not head:
            return None
        mp = defaultdict()
        temp = head
        while temp:
            mp[temp] = Node(temp.val)
            temp = temp.next
        temp = head
