        set2 = {}

        def memo(ind: int, n: int, s: str, temp: str, st: Dict):
            if ind == n:
                return 1
            if (ind, temp) in st:
                return st[(ind, temp)]
            include = memo(ind + 1, n, s, temp + s[ind], st)
            exclude = memo(ind + 1, n, s, temp, st)
            st[(ind, temp)] = include + exclude
            return st[(ind, temp)]

