                        nj = j + col[k]
                        if is_valid(ni, nj):
                            v = ni * m + nj
                            dset.union_by_size(u, v)
        ans = max(dset.size[i] for i in range(n * m))
        for i in range(n):
            for j in range(m):
                if grid[i][j] == 0:
